/**
 * Segmented control (spec/02 §2.7): [label] (the legend) over 2–4 equal columns in one 1 dp borderStrong frame (8 dp
 * radius) with 1 dp lines between; each face ≥ 48 dp, the word in label, centred, on one line or two (D99 (1); an option
 * that does not fit so makes the whole control an SbSelectField with the same API). Chosen = the 3 dp accent bottom
 * edge + check 16 dp + title weight + link colour, never filled; hover hoverFill, pressed pressedFill; the focus ring
 * 4 dp inside the face. [disabledOptions]: the word textMuted, no target; a chosen one keeps check, weight and edge,
 * the edge borderStrong. [enabled] = false greys frame, lines and legend. TalkBack: radio buttons in a group. Keys:
 * one Tab stop (the chosen option); ← → choose the previous / next usable option and wrap (swapped right to left).
 */
@Composable
fun <T> SbSegmented(
    label: String,
    options: List<Pair<T, String>>,
    selected: T,
    onChange: (T) -> Unit,
    modifier: Modifier = Modifier,
    enabled: Boolean = true,
    disabledOptions: Set<T> = emptySet(),
) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val rtl = LocalLayoutDirection.current == LayoutDirection.Rtl
    val usable = options.indices.filter { enabled && options[it].first !in disabledOptions }
    val chosen = options.indexOfFirst { it.first == selected }
    val start = if (chosen in usable) chosen else usable.firstOrNull() ?: -1
    var stop by remember(start) { mutableStateOf(start) }
    val requesters = remember(options.size) { List(options.size) { FocusRequester() } }
    val frame = if (usable.isEmpty()) c.border else c.borderStrong
    val measurer = rememberTextMeasurer()
    val chosenStyle = ty.label.copy(fontWeight = ty.title.fontWeight)
    BoxWithConstraints(modifier) {
        // D99 (1): every option must fit its column on at most two lines, its words whole, with room for the
        // check (the column less 4 dp at both sides, the 16 dp check and its 4 dp gap, at the title weight,
        // whichever option is chosen); else the control is the select field with the same options, choice and
        // disabled options
        val fits = with(LocalDensity.current) {
            val line = t.borderWidth.control.toPx()
            val column = (constraints.maxWidth - (options.size + 1) * line) / options.size
            val inner = (column - 2 * t.space.s1.toPx() - t.size.iconSm.toPx() - t.space.s1.toPx()).toInt().coerceAtLeast(0)
            options.all { (_, word) ->
                measurer.sbWidestWord(word, chosenStyle) <= inner &&
                    measurer.measure(word, chosenStyle, constraints = Constraints(maxWidth = inner)).lineCount <= 2
            }
        }
        if (!fits) {
            SbSelectField(label, options, selected, onChange, enabled = enabled, disabledOptions = disabledOptions)
            return@BoxWithConstraints
        }
        Column(verticalArrangement = Arrangement.spacedBy(t.space.s1)) {
            Text(label, style = ty.label, color = if (usable.isEmpty()) c.textMuted else c.text)
            Row(
                Modifier
                    .fillMaxWidth()
                    .height(IntrinsicSize.Min)
                    .clip(t.shapes.control)
                    .border(t.borderWidth.control, frame, t.shapes.control)
                    .padding(t.borderWidth.control)
                    .selectableGroup(),
            ) {
                options.forEachIndexed { i, (value, word) ->
                    if (i > 0) Box(Modifier.width(t.borderWidth.control).fillMaxHeight().background(frame))
                    val interaction = remember { MutableInteractionSource() }
                    val hovered by interaction.collectIsHoveredAsState()
                    val pressed by interaction.collectIsPressedAsState()
                    val on = i in usable
                    val isChosen = i == chosen
                    val fill = when {
                        !on -> Color.Transparent
                        pressed -> c.pressedFill
                        hovered -> c.hoverFill
                        else -> Color.Transparent
                    }
                    val ink = when {
                        !on -> c.textMuted
                        isChosen -> c.link
                        else -> c.text
                    }
                    val edge = if (on) c.accent else c.borderStrong
                    Row(
                        Modifier
                            .weight(1f)
                            .heightIn(min = t.size.targetTouch)
                            .background(fill)
                            .sbCurrentEdge(isChosen, SbEdge.Bottom, edge, t.borderWidth.strong)
                            .sbSegmentFocusRing(interaction)
                            .focusRequester(requesters[i])
                            .focusProperties { if (i != stop) canFocus = false }
                            .onPreviewKeyEvent { e ->
                                val to = sbRowKey(e, i, usable, rtl, homeEnd = false) ?: return@onPreviewKeyEvent false
                                stop = to
                                onChange(options[to].first)
                                requesters[to].requestFocus()
                                true
                            }
                            .selectable(
                                selected = isChosen,
                                interactionSource = interaction,
                                indication = null,
                                enabled = on,
                                role = Role.RadioButton,
                                onClick = { onChange(value) },
                            )
                            .padding(horizontal = t.space.s1),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(t.space.s1, Alignment.CenterHorizontally),
                    ) {
                        if (isChosen) Icon(SebaroIcons.Outline16.Check, contentDescription = null, tint = ink, modifier = Modifier.size(t.size.iconSm))
                        SbWrapText(word, if (isChosen) chosenStyle else ty.label, ink, center = true)
                    }
                }
            }
        }
    }
}

/** The focus ring of a segment: 2 dp focus, 4 dp inside the face (the web's outline-offset -4px), square. */
@Composable
private fun Modifier.sbSegmentFocusRing(interaction: InteractionSource): Modifier {
    val focused by interaction.collectIsFocusedAsState()
    val color = SebaroTheme.colors.focus
    val focus = SebaroTheme.tokens.focus
    return drawWithContent {
        drawContent()
        if (focused) {
            val w = focus.width.toPx()
            val inset = (focus.offset + focus.width).toPx() - w / 2f
            drawRect(color, Offset(inset, inset), Size(size.width - 2 * inset, size.height - 2 * inset), style = Stroke(width = w))
        }
    }
}

/**
 * The keys of a one-row choice (segments, tabs): from option [at], → / ← to the next / previous of the [usable]
 * indices with wrap (swapped when [rtl]); with [homeEnd] Home / End to the first / last. Null = not this row's key
 * (key up, Ctrl, Alt, Meta, any other key), so it passes on.
 */
internal fun sbRowKey(e: KeyEvent, at: Int, usable: List<Int>, rtl: Boolean, homeEnd: Boolean): Int? {
    if (e.type != KeyEventType.KeyDown || e.isCtrlPressed || e.isAltPressed || e.isMetaPressed || usable.isEmpty()) return null
    val k = usable.indexOf(at)
    if (k < 0) return null
    val next = if (rtl) Key.DirectionLeft else Key.DirectionRight
    val previous = if (rtl) Key.DirectionRight else Key.DirectionLeft
    return when {
        e.key == next -> usable[(k + 1) % usable.size]
        e.key == previous -> usable[(k - 1 + usable.size) % usable.size]
        homeEnd && e.key == Key.MoveHome -> usable.first()
        homeEnd && e.key == Key.MoveEnd -> usable.last()
        else -> null
    }
}
